package mx.com.mesaregia.inventario.api.controller;
import jakarta.validation.Valid; import mx.com.mesaregia.inventario.application.service.LimiteInventarioService; import mx.com.mesaregia.inventario.api.request.LimiteInventarioRequest; import mx.com.mesaregia.inventario.api.response.LimiteInventarioResponse; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/inventario/limites") public class LimiteController {private final LimiteInventarioService s;public LimiteController(LimiteInventarioService s){this.s=s;}@PutMapping("/{idProducto}")@PreAuthorize("hasAuthority('inventario.gestionar')")public LimiteInventarioResponse put(@PathVariable Long idProducto,@RequestParam Long idAlmacen,@Valid @RequestBody LimiteInventarioRequest r){return s.configurar(idProducto,idAlmacen,r);} }
